var i=[{title:`Jak wygląda stały wysiłek`,text:`Twoje tętno nie będzie idealnie płaską linią. Tempo i oddech mogą się zmieniać przy wzniesieniach, upale lub zmęczeniu, podczas gdy ogólny wysiłek pozostaje pod kontrolą. Wybierz aktywność, którą możesz kontynuować bez częstych przerw i niechlujnej techniki.`},{title:`Wybierz intensywność`,text:`W wielu ogólnych treningach sprawnościowych umiarkowana intensywność jest odczuwalna jako praca, ale nadal pozwala prowadzić rozmowę. Test mowy bywa bardziej użyteczny niż gonienie za ustaloną prędkością lub liczbą tętna. Osoby wytrenowane mogą wykonywać intensywną pracę ciągłą, ale początkującym zwykle lepiej służy łagodny start.`},{title:`Dodawaj czas przed prędkością`,text:`Zacznij od praktycznej ilości, na przykład 10–20 minut szybkiego marszu lub spokojnej jazdy na rowerze. Wydłużaj trening małymi krokami, a potem pomyśl o szybszym tempie lub większym oporze maszyny. Jeśli podniesiesz czas, prędkość i częstotliwość naraz, trudniej stwierdzić, co powoduje Twoje zmęczenie i jak dobrze się regenerujesz.`},{title:`Dostosuj do warunków`,text:`Marsz i jazda na rowerze to łatwiejszy wybór, jeśli chcesz mniejszego uderzenia, podczas gdy jogging dodaje powtarzające się lądowania. W domu maszyny pozwalają utrzymać dość stałe ustawienia, ale na zewnątrz nachylenia i pogoda zmieniają odczucie tego samego wyświetlanego tempa. Używaj odczucia, jak ciężko jest, by uczciwie porównywać treningi. Robisz postępy, gdy ta sama trasa wydaje się łatwiejsza lub wygodny trening się wydłuża, i nie musisz doprowadzać każdego treningu do granic możliwości.`}];var o=[{label:`CDC: zalecenia dotyczące aktywności fizycznej dorosłych`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`},{label:`CDC: pomiar intensywności wysiłku i test mowy`,url:`https://www.cdc.gov/physicalactivity/basics/measuring/index.html`},{label:`CDC: ćwiczenia w upale`,url:`https://www.cdc.gov/heat-health/risk-factors/heat-and-athletes.html`}];var t={sections:i,sources:o};export{t as default,i as sections,o as sources};